mapper.update:
UPDATE "daiya_revisions"
   SET "rosen_id"            = #{rosenId}
     , "daiya_revision_name" = #{daiyaRevisionName}
     , "service_start_date"  = CAST(#{serviceStartDate} AS date)
     , "service_end_date"    = CAST(#{serviceStartDate} AS date) - 1

 WHERE "del_flag"            = 0
   AND "daiya_revision_id"   = #{daiyaRevisionId}
   AND "rosen_id"            = #{rosenId}
   AND "service_end_date"    = DATE '9999-12-31'

mapper.insert:
INSERT INTO "daiya_revisions" (
            "rosen_id"
          , "daiya_revision_name"
          , "service_start_date"

        )
        VALUES (
            #{rosenId}
          , #{daiyaRevisionName}
          , CAST(#{serviceStartDate} AS date)

        )

mapper.sql:
FROM "daiya_revisions" "a" INNER JOIN "lines" "b" ON "b"."del_flag" = 0 AND "b"."available_flag" = 1 AND "a"."rosen_id" = "b"."rosen_id" INNER JOIN "agencies" "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "b"."business_corp_id" WHERE "a"."del_flag" = 0
AND "a"."rosen_id" = #{rosenId}
AND "ag"."business_corp_id" = #{businessCorpId}
AND CAST(#{serviceStartDate} AS date) <= "a"."service_end_date"
AND CAST(#{serviceEndDate} AS date) >= "a"."service_start_date"

mapper.select:
SELECT "l"."rosen_id" , "d"."service_start_date" , "d"."daiya_revision_id" FROM "lines" "l" INNER JOIN "daiya_revisions" "d" ON "d"."del_flag" = 0 AND "l"."rosen_id" = "d"."rosen_id" INNER JOIN "agencies" "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "l"."business_corp_id" = "a"."business_corp_id" WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1
AND "a"."business_corp_id" = #{businessCorpId}
ORDER BY "d"."service_start_date" DESC
